package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"regexp"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(10)
}

// stripDangerousKeywords removes obvious attack patterns
func stripDangerousKeywords(input string) string {
	// Remove common SQL keywords used in attacks
	re := regexp.MustCompile(`(?i)(DROP|ALTER|TRUNCATE|CREATE|GRANT|REVOKE)\s`)
	return re.ReplaceAllString(input, "")
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortBy := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category required", 400)
		return
	}

	// Apply keyword filter
	category = stripDangerousKeywords(category)

	// Validate sort column against allowlist
	allowedSorts := map[string]bool{"price": true, "name": true, "created_at": true}
	if sortBy == "" || !allowedSorts[sortBy] {
		sortBy = "name"
	}

	// Build query - minPrice is validated as numeric separately
	var query string
	if minPrice != "" {
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = '%s' AND price >= %s ORDER BY %s LIMIT 50",
			category, minPrice, sortBy,
		)
	} else {
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = '%s' ORDER BY %s LIMIT 50",
			category, sortBy,
		)
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	type Product struct {
		ID    int     `json:"id"`
		Name  string  `json:"name"`
		Price float64 `json:"price"`
		Desc  string  `json:"description"`
	}

	var results []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Desc); err != nil {
			continue
		}
		results = append(results, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
